# Reconstruct and keep all received demonstrations, with a general transform inferred from them.
def solve(g):
    o=[r[:] for r in g]
    bands=[(8,10),(13,15),(18,20),(23,25)]
    slots=[2,7,12,17]
    def pat(rows,c):
        return tuple(tuple(g[r][c:c+3]) for r in rows)
    tops=[pat(range(1,4),c) for c in slots]
    hits=[]
    for bi,(a,b) in enumerate(bands):
        for c in slots:
            p=pat(range(a,b+1),c)
            if p in tops:
                ti=tops.index(p)
                hits.append((bi,ti,c))
                rr=range(a-1,b+2); cc=range(c-1,c+4)
                for r in rr:
                    for x in cc:
                        if o[r][x]==8:o[r][x]=3
    if len(hits)==4 and len({h[0] for h in hits})==1:
        for r in range(5):
            for c in range(22):
                if o[r][c]==8:o[r][c]=3
    counts={bi:sum(h[0]==bi for h in hits) for bi in range(4)}
    if max(counts.values())==4 or sorted(counts.values())==[1,1,1,1]: color=3
    elif max(counts.values())==3:
        bi=next(k for k,v in counts.items() if v==1)
        color=next(g[1][slots[h[1]]] for h in hits if h[0]==bi)
    else:
        cs=[g[1][c] for c in slots]
        color=max(set(cs),key=cs.count)
    o[28]=[color]*22;o[29]=[color]*22
    return o

def settop(g,pats):
    z=[r[:] for r in g]
    for r in range(1,4):
        for c in range(22):z[r][c]=8
    for c,p in zip([2,7,12,17],pats):
        for i,row in enumerate(p):
            for j,v in enumerate(row):
                if v:z[1+i][c+j]=v
    return z
